PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, mode TEXT NOT NULL, config TEXT NOT NULL, strategy TEXT NOT NULL, data_hash TEXT NOT NULL, schedule TEXT NOT NULL, cursor TEXT, cash INTEGER NOT NULL, initial INTEGER NOT NULL, paused INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL, code_version TEXT NOT NULL DEFAULT '0.1.0');
CREATE TABLE IF NOT EXISTS instruments(id TEXT PRIMARY KEY, symbol TEXT NOT NULL, exchange TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'INR', tick INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS candles(run TEXT REFERENCES runs(id), instrument TEXT REFERENCES instruments(id), time TEXT, payload TEXT NOT NULL, retrieved TEXT NOT NULL, PRIMARY KEY(run,instrument,time));
CREATE TABLE IF NOT EXISTS sessions(run TEXT REFERENCES runs(id), day TEXT, equity INTEGER NOT NULL, halted INTEGER NOT NULL DEFAULT 0, trades INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(run,day));
CREATE TABLE IF NOT EXISTS candidates(id TEXT PRIMARY KEY, run TEXT REFERENCES runs(id), instrument TEXT REFERENCES instruments(id), time TEXT NOT NULL, expiry TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL, evidence TEXT NOT NULL, stop INTEGER NOT NULL, target INTEGER NOT NULL, reason TEXT NOT NULL DEFAULT '', UNIQUE(run,instrument,time));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, candidate TEXT REFERENCES candidates(id), context TEXT NOT NULL, model TEXT NOT NULL, prompt TEXT NOT NULL, status TEXT NOT NULL, response TEXT, error TEXT, requested TEXT NOT NULL, completed TEXT, latency REAL, usage TEXT, allowance REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS decisions(id INTEGER PRIMARY KEY, candidate TEXT REFERENCES candidates(id), revision INTEGER NOT NULL, action TEXT NOT NULL, actor TEXT NOT NULL, time TEXT NOT NULL, UNIQUE(candidate,revision));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, candidate TEXT UNIQUE REFERENCES candidates(id), state TEXT NOT NULL, approved TEXT NOT NULL, qty INTEGER NOT NULL, reserve INTEGER NOT NULL, risk INTEGER NOT NULL, reason TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS positions(id TEXT PRIMARY KEY, run TEXT REFERENCES runs(id), instrument TEXT REFERENCES instruments(id), candidate TEXT UNIQUE REFERENCES candidates(id), qty INTEGER NOT NULL, entry INTEGER NOT NULL, entry_fee INTEGER NOT NULL, stop INTEGER NOT NULL, target INTEGER NOT NULL, risk INTEGER NOT NULL, opened TEXT NOT NULL, mark INTEGER NOT NULL, marked TEXT NOT NULL, closed TEXT, exit INTEGER, exit_fee INTEGER, reason TEXT, exit_requested TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_open ON positions(run,instrument) WHERE closed IS NULL;
CREATE TABLE IF NOT EXISTS fills(id TEXT PRIMARY KEY, run TEXT REFERENCES runs(id), position TEXT REFERENCES positions(id), side TEXT NOT NULL, qty INTEGER NOT NULL, price INTEGER NOT NULL, fee INTEGER NOT NULL, time TEXT NOT NULL, UNIQUE(position,side));
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY, run TEXT REFERENCES runs(id), fill TEXT UNIQUE REFERENCES fills(id), amount INTEGER NOT NULL, time TEXT NOT NULL, kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, run TEXT REFERENCES runs(id), time TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equity(run TEXT REFERENCES runs(id), time TEXT, value INTEGER NOT NULL, uncertain INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(run,time));
CREATE TABLE IF NOT EXISTS worker(run TEXT PRIMARY KEY REFERENCES runs(id), last_fetch TEXT, last_processed TEXT, next_check TEXT, error TEXT, lease_until TEXT);
CREATE INDEX IF NOT EXISTS outcomes_time ON positions(run,closed);
